//! Validated value types.
//!
//! Both newtypes are generated by [`nutype`], which emits a checked
//! `try_new` constructor plus a dedicated `*Error` enum. Because the serde
//! impls go through the same constructor, *deserialising* an invalid value
//! fails exactly like `try_new` does — the invariant cannot be smuggled in
//! from JSON.

use nutype::nutype;

/// A non-empty component (service, module, task) name.
#[nutype(
    validate(not_empty),
    derive(
        Debug,
        Clone,
        PartialEq,
        Eq,
        PartialOrd,
        Ord,
        Hash,
        Serialize,
        Deserialize,
        FromStr,
        Display,
        Deref,
        AsRef
    )
)]
pub struct Component(String);

/// A percentage in the inclusive range `0..=100`.
#[nutype(
    validate(greater_or_equal = 0, less_or_equal = 100),
    derive(
        Debug,
        Clone,
        Copy,
        PartialEq,
        Eq,
        PartialOrd,
        Ord,
        Hash,
        Serialize,
        Deserialize,
        FromStr,
        Display,
        Deref,
        AsRef
    )
)]
pub struct Percent(u8);
